const SCAN_PASS = (process.env.BOBAI_SCAN_PASS || '').trim();

async function fetchJson(path) {
  const res = await fetch(path.startsWith('http') ? path : BASE + path, { headers: { accept: 'application/json', ...(SCAN_PASS ? { 'x-scan-pass': SCAN_PASS } : {}) } });
  if (!res.ok) {
    // The REST mirror answers a refusal in plain words ({"error": "..."}); that
    // sentence is the answer, not "HTTP 400" (2026-10-05).
    const body = await res.json().catch(() => null);
    // …with its code and hint (2026-10-09), carried on to the isError result below.
    const e = new Error(body?.error ? String(body.error) : body ? JSON.stringify(body) : `GET ${path} -> HTTP ${res.status}`);
    if (body?.code) { e.code = String(body.code); e.hint = body.hint ? String(body.hint) : undefined; }
    throw e;
  }
  return res.json();
}

async function runTool(name, args) {
  const tool = TOOLS.find(t => t.name === name);
  if (!tool) throw new Error('Unknown tool: ' + name);
  // The five the package lacked (A-Z 2026-11-21: 25 tools here, 30 hosted): they keep state on the hosted side (a rug
  // watch, the board, the escrow list), so the package asks the hosted server itself and answers what it answers.
  if (tool.forward) {
    const res = await fetch(BASE + '/mcp', { method: 'POST', headers: { 'content-type': 'application/json', accept: 'application/json', 'user-agent': 'bobai-mcp-stdio/' + SERVER_INFO.version },
      body: JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name, arguments: args || {} } }) });
    const j = await res.json().catch(() => null);
    if (!j) throw new Error(`${name}: the hosted server did not answer (http ${res.status})`);
    if (j.error) throw new Error(j.error.message || String(j.error));
    const text = j.result?.content?.[0]?.text || '';
    if (j.result?.isError) throw new Error(text || `${name} refused`);
    if (j.result?.structuredContent) return j.result.structuredContent;
    try { return JSON.parse(text); } catch { return { answer: text }; }
  }
  if (name === 'bobai_wallet_balance') {
    const address = String(args?.address || '');
    if (!/^0x[0-9a-fA-F]{40}$/.test(address)) throw new Error('Invalid BSC address (expected 0x + 40 hex chars)');
    return fetchJson('/api/wallet?address=' + address);
  }
  // The employment census is one static file; the hosted tool narrows it to
  // one provider in the worker, so this does the same here (2026-10-05: the
  // address was accepted and ignored).
  if (name === 'bnb_agent_employment') {
    const want = String(args?.address || '').trim().toLowerCase();
    if (want && !/^0x[0-9a-f]{40}$/.test(want)) throw new Error('address must be a provider address: 0x followed by 40 hex characters. Omit it for the whole kernel.');
    const j = await fetchJson(tool.rest);
    if (want) {
      const p = (j.providers || []).find((x) => x.address === want);
      if (!p) return { address: want, jobs: 0, note: 'This address does not appear as a provider on any job in the kernel.', measured_at: j.measured_at, source: j.source };
      return { ...p, of_all_jobs: j.jobs?.read, measured_at: j.measured_at, method: j.method, source: j.source };
    }
    return { ...j.jobs, top_providers: (j.providers || []).slice(0, 10), measured_at: j.measured_at, method: j.method, full_data: BASE + tool.rest, human_readable: BASE + '/registry' };
  }
  // One agent's chart (2026-10-14, as the hosted tool): the verdict and its parts, the long series left on the page.
  if (name === 'bnb_agent_chart') {
    const id = String(args?.agent_id ?? '').replace(/[^0-9]/g, '');
    if (!id) throw new Error('Give the agent’s ERC-8004 id on BNB Smart Chain (a number), e.g. 302257.');
    const j = await fetchJson(tool.rest + id);
    const { series, ...pulse } = j.pulse || {};
    return { ...j, pulse, jobs: j.jobs ? { ...j.jobs, trades: (j.jobs.trades || []).filter((t) => t.status !== 'OPEN').slice(0, 10), by_day: undefined } : null, chart: `${BASE}/agent/${id}` };
  }
  // The measurement tools pass their arguments through as query parameters,
  // named as the REST mirror names them.
  if (tool.params) {
    const qs = new URLSearchParams();
    for (const [arg, key] of Object.entries(tool.params)) if (args?.[arg] != null && args[arg] !== '') qs.set(key, String(args[arg]));
    const required = tool.inputSchema.required || [];
    for (const r of required) if (!qs.has(tool.params[r])) throw new Error(`${name}: ${r} is required`);
    return fetchJson(tool.rest + (qs.toString() ? '?' + qs.toString() : ''));
  }
  const data = await fetchJson(tool.rest);
  if (name === 'bobai_burned') return { symbol: data.symbol, burned: data.burned, note: 'Permanently sent to dead/zero address — irreversible' };
  if (name === 'bobai_circulating_supply') return { symbol: 'BOBAI', circulatingSupply: String(data.circulatingSupply ?? data.circulating_supply) };
  return data;
}

async function readResource(uri) {
  const r = RESOURCES.find(x => x.uri === uri);
  if (!r) throw new Error('Unknown resource: ' + uri);
  const res = await fetch(uri);
  if (!res.ok) throw new Error(`GET ${uri} -> HTTP ${res.status}`);
  return { uri, mimeType: r.mimeType, text: await res.text() };
}

function getPrompt(name, args) {
  if (name === 'evaluate_bobai') {
    return {
      description: PROMPTS[0].description,
      messages: [{ role: 'user', content: { type: 'text', text: [
        'You are evaluating the $BOBAI token (Brain On BNB AI) on BNB Chain. Use this server\'s tools and stay neutral — verify, don\'t trust.',
        '1. Call bobai_token_info — confirm contract, supply, amount burned, renounced/verified flags.',
        '2. Call bobai_price and bobai_liquidity — note liquidity depth, LP-burned %, and the price impact for your intended size.',
        '3. Call bobai_activity — open the last burn tx on BscScan to confirm the buyback flywheel actually runs.',
        '4. Call bobai_tokenomics — understand the value-accrual design and its trust properties.',
        '5. Cross-check at least one claim independently on-chain (e.g. balanceOf(0x…dEaD) on the token contract, or getReserves() on the pair).',
        'Then give a balanced assessment: strengths, risks (meme token, small liquidity means high price impact, burn cadence depends on volume), and anything you could not verify. This is research, not financial advice.',
      ].join('\n') } }],
    };
  }
  if (name === 'prepare_bobai_swap') {
    const wallet = args?.wallet && /^0x[0-9a-fA-F]{40}$/.test(args.wallet) ? args.wallet : null;
    return {
      description: PROMPTS[1].description,
      messages: [{ role: 'user', content: { type: 'text', text: [
        'You are preparing (not necessarily executing) a $BOBAI swap on PancakeSwap V2. $BOBAI is fee-on-transfer (3% tax) — a naive swap reverts.',
        '1. Call bobai_dex_info — router, pair, swap paths, the *SupportingFeeOnTransferTokens methods and slippage >= 15% (1500 bps).',
        '2. Call bobai_price and bobai_liquidity — check the price-impact estimate for your size; the 3% transfer tax comes on top.',
        wallet
          ? '3. Call bobai_wallet_balance with address ' + wallet + ' — confirm it holds the BNB for the swap plus gas.'
          : '3. Optionally call bobai_wallet_balance — confirm the wallet holds the BNB for the swap plus gas.',
        '4. Call bobai_purchase_guide — ready-to-run viem code (on-chain quote minus 15% slippage, explicit RPC).',
        'Sanity rules: test with a small amount first, verify token/router/pair on BscScan yourself, never expose a private key holding significant funds. Not financial advice.',
      ].join('\n') } }],
    };
  }
  throw new Error('Unknown prompt: ' + name);
}

const STRUCTURED = new Set(['bsc_token_preflight', 'bsc_pool_scan', 'pancakeswap_best_route']);
const ok = (id, result) => ({ jsonrpc: '2.0', id, result });
const err = (id, code, message) => ({ jsonrpc: '2.0', id, error: { code, message } });
const send = (msg) => process.stdout.write(JSON.stringify(msg) + '\n');

async function handle(req) {
  if (Array.isArray(req)) return send(err(null, -32600, 'Invalid request: batch requests are not supported; send one JSON-RPC object per line.'));
  const { id, method, params } = req || {};
  if (typeof method !== 'string') { if (id !== undefined) send(err(id, -32600, 'Invalid request')); return; }
  if (method.startsWith('notifications/')) return;
  try {
    if (method === 'initialize') return send(ok(id, { protocolVersion: PROTOCOL, capabilities: { tools: {}, resources: {}, prompts: {} }, serverInfo: SERVER_INFO, instructions: INSTRUCTIONS }));
    if (method === 'tools/list') return send(ok(id, { tools: TOOLS.map(({ rest, params: _p, ...t }) => ({ ...t, annotations: { ...(t.annotations || {}), readOnlyHint: true, destructiveHint: false } })) }));
    if (method === 'tools/call') {
      // As on the hosted server: a tool that refuses ("that is not a BSC
      // token") has answered, so the model reads it as a result with isError
      // rather than a JSON-RPC error many clients swallow.
      try {
        const out = await runTool(params?.name, params?.arguments || {});
        // The JSON itself beside the text for the three trading reads (2026-10-09), as on the hosted server.
        return send(ok(id, { content: [{ type: 'text', text: JSON.stringify(out, null, 2) }],
          ...(STRUCTURED.has(params?.name) && out && typeof out === 'object' ? { structuredContent: out } : {}) }));
      } catch (e) {
        const msg = e.message || String(e);
        if (!e.code || typeof e.code !== 'string') return send(ok(id, { content: [{ type: 'text', text: msg }], isError: true }));
        return send(ok(id, { content: [{ type: 'text', text: `${msg}\n\ncode: ${e.code}${e.hint ? ` — ${e.hint}` : ''}` }], structuredContent: { error: msg, code: e.code, hint: e.hint ?? null }, isError: true }));
      }
    }
    if (method === 'resources/list') return send(ok(id, { resources: RESOURCES }));
    if (method === 'resources/templates/list') return send(ok(id, { resourceTemplates: [] }));
    if (method === 'resources/read') return send(ok(id, { contents: [await readResource(params?.uri)] }));
    if (method === 'prompts/list') return send(ok(id, { prompts: PROMPTS }));
    if (method === 'prompts/get') return send(ok(id, getPrompt(params?.name, params?.arguments || {})));
    if (method === 'ping') return send(ok(id, {}));
    return send(err(id ?? null, -32601, 'Method not found: ' + method));
  } catch (e) {
    return send(err(id ?? null, -32000, e.message || String(e)));
  }
}

const rl = createInterface({ input: process.stdin, terminal: false });
rl.on('line', (line) => {
  line = line.trim();
  if (!line) return;
  let req;
  try { req = JSON.parse(line); } catch { return send(err(null, -32700, 'Parse error')); }
  handle(req);
});
rl.on('close', () => process.exit(0));
